INSERT INTO `cars` VALUES (6,'STARGAZER Cartenz X','stargazer-cartenz-x','MPV',374650000.00,'<p><strong>STARGAZER Cartenz X – Mobil Canggih untuk Jalanan Indonesia<br></strong>Dirancang khusus untuk menghadapi karakter jalan di Indonesia, Hyundai Stargazer Cartenz X hadir dengan desain baru yang lebih berkelas dan teknologi terkini. Mobil ini siap menjadi partner perjalanan yang andal, menemani setiap perjalananmu dengan kenyamanan, keamanan, dan tanpa rasa khawatir.</p><p><br></p><p><strong>Fitur Canggih untuk Segala Kondisi Jalan</strong></p><p>Taklukkan berbagai kondisi jalanan Indonesia—dari kemacetan kota hingga jalur berliku—dengan percaya diri. Berkat teknologi pintar, sistem keamanan modern, dan konektivitas canggih, setiap perjalanan terasa lebih aman dan terkendali.</p><p><br></p><p><strong>Lane Keeping Assist (LKA)</strong></p><p>Nikmati perlindungan ekstra dengan fitur <strong>Lane Keeping Assist (LKA)</strong>.<br> Sistem ini akan:</p><ul><li>&nbsp;Mendeteksi saat kendaraan keluar jalur tanpa sein&nbsp;</li><li>&nbsp;Memberikan peringatan otomatis kepada pengemudi&nbsp;</li><li>&nbsp;Membantu mengoreksi arah kemudi agar tetap berada di jalur aman&nbsp;</li></ul><p>Hasilnya? Perjalanan lebih stabil, aman, dan nyaman di berbagai kondisi jalan.</p>','[\"Shift By Wire (SBW)\",\"Driver Ventilated Seat* Driver Power Seat (8-way)*\",\"BOSE\\u2122 Premium Audio System\",\"Paddle Shifter\"]',NULL,'cars/01KRWHAF0G847ZP6BX8MND8YSG.png','cars/hero/01KQVQ5SCZ084JTVJA8Z52J1RW.avif','[\"cars\\/gallery\\/01KQVP2NGQ29CMDZQ27R6ZW41V.jpg\",\"cars\\/gallery\\/01KQVP2NH2VKEK0V93A2657B98.jpg\",\"cars\\/gallery\\/01KQVP2NHDTFJ936H5FH1248CD.jpg\",\"cars\\/gallery\\/01KQVP2NHTY5AKXER24EJ1FZ9G.jpg\",\"cars\\/gallery\\/01KQVP2NJ470CXEXWX3WT7P8DY.jpg\",\"cars\\/gallery\\/01KQVP2NJJP9HR65AFBWZMEKJ7.jpg\",\"cars\\/gallery\\/01KQVP2NJRQ1PGAZ26DHCEKWJK.jpg\"]','cars/flyers/01KQVP2NJZB5K9EENS5R0DTRZ4.pdf',1,'2026-05-05 02:04:04','2026-05-17 20:16:54'),(7,'New CRETA Alpha','new-creta-alpha','SUV',459850000.00,'<h2>Bolder from every angle.</h2><p>Desain eksterior yang berani berpadu dengan interior yang tegas dan modern, hadirkan karakter kuat di setiap perjalanan.</p><p><br></p><h2>Bold meets technology.</h2><p>Teknologi canggih yang dirancang untuk meningkatkan keselamatan, kenyamanan, dan konektivitas.</p><p><br></p><h2>Be Unstoppable</h2><p>Bersama the New CRETA, tak ada yang bisa hentikanmu meraih ambisi. Dengan desain progresif dan futuristik, dirancang untuk Anda makin percaya diri taklukkan tantangan di depan.</p><p><br></p>','[\"Power Tailgate\",\"Front-row Ventilated Seats\",\"BOSE\\u00ae Premium audio system\",\"Console Armrest with Air Purifier\"]',NULL,'cars/01KQVT6HCQ681ENHX47RV8AFBZ.png','cars/hero/01KQVT6HD3XY2NPXW2E0A8Q9Q3.jpg','[\"cars\\/gallery\\/01KQVT6HDKKB32GYX5AXZEZB9Z.jpg\",\"cars\\/gallery\\/01KQVT6HE72SMVSVDB82T4H8XD.jpg\",\"cars\\/gallery\\/01KQVT6HEMJW8G6KR7S2VA5FCP.jpg\",\"cars\\/gallery\\/01KQVT6HEY7ZNR3FP0P5ZG3ZAG.jpg\",\"cars\\/gallery\\/01KQVT6HF946Z3S7PZXWCH98GE.jpg\",\"cars\\/gallery\\/01KQVT6HFGY7XTYFG5QY2PZXP1.jpg\",\"cars\\/gallery\\/01KQVT6HFSFHWYSYRWMEV0B7J5.jpg\"]','cars/flyers/01KQVTK6S3NQ8BZXZ746NCHKJK.pdf',1,'2026-05-05 03:16:05','2026-05-17 20:20:59'),(9,'The all-new PALISADE','the-all-new-palisade','HEV',1131900000.00,'<h2><strong>Premium has its shape.</strong></h2><p>Desain elegan, detail berani, dan proporsi yang dinamis. The all-new PALISADE Hybrid hadir dengan tampilan tegas yang mencerminkan rasa percaya diri serta memperkuat identitas premiumnya secara keseluruhan.</p><p><br></p><h2><strong>Premium has its comfort.</strong></h2><p>Kabin luas yang menenangkan, fitur canggih yang memanjakan. The all-new PALISADE Hybrid menyuguhkan kenyamanan modern dalam setiap perjalanan, dirancang untuk mereka yang tahu arti kualitas sesungguhnya.</p>','[\"Hyundai SmartSense\",\"Bluelink, connects with your car.\",\"6-way power 2nd row Captain Seats dan Power Sliding & Folding 3rd row seats\",\"Fingerprint Authentication* & 100W USB-C Charging Ports\",\"Ergo-motion Driver Seat* & Relaxation Seats\"]',NULL,'cars/01KR9F936FC1KCAQ3GGBBT7SDP.png','cars/hero/01KR9F936NPX4RSSCESWPVH09Z.avif','[\"cars\\/gallery\\/01KR9F936W5F8GSGFG7A7FJQC8.avif\",\"cars\\/gallery\\/01KR9F9373X34TNFH7EQBK823M.avif\",\"cars\\/gallery\\/01KR9F9378E8C3W6R2K8WV1BXM.avif\",\"cars\\/gallery\\/01KR9F937E4QBVB260YYDQDQ0H.avif\",\"cars\\/gallery\\/01KR9F937NHWFTT4Y0JKCSEV2N.avif\"]',NULL,1,'2026-05-10 10:34:37','2026-05-10 10:34:37'),(10,'Hyundai Stargazer Cartenz ','hyundai-stargazer-cartenz','MPV',280500000.00,'<h2><strong>Makin nyaman, keluarga jadi tenang.</strong></h2><p>Selain ruang yang luas untuk anak-anak dan seluruh anggota keluarga, STARGAZER Cartenz dilengkapi fitur keamanan, kompartemen multifungsi hingga konektivitas yang makin mempermudah Anda bikin perjalanan menenangkan untuk keluarga.</p><p><br></p><h2><strong>Hyundai SmartSense</strong></h2><p>Teknologi cerdas yang dirancang untuk mendeteksi potensi bahaya di jalan untuk tingkatkan keselamatan berkendara bagi pengemudi dan penumpang.</p>','[\"6 airbag\",\"Lane Keeping Assist (LKA)\",\"Forward Collision-avoidance Assist with Junction Turning (FCA-JT)\",\"Blind-spot Collision-avoidance Assist (BCA)\",\"Parking Distance Warning (PDW)\"]',NULL,'cars/01KRWH758XQM5SHEE880EAA3E2.png','cars/hero/01KRYV736PC5Z2CE9W9GF9DPRP.avif','[\"cars\\/gallery\\/01KRYVAYCK5TQ6AQZRBMNA1DR9.avif\",\"cars\\/gallery\\/01KRYVAYCTGQ75AA9ZD32P9ZZS.avif\",\"cars\\/gallery\\/01KRYVAYCYYGXGC2HWWMB2ASN0.avif\",\"cars\\/gallery\\/01KRYVAYD27RMR67XMGT7CDP5Z.avif\",\"cars\\/gallery\\/01KRYVAYD7TZC7YJ7SBFRJ60NX.avif\",\"cars\\/gallery\\/01KRYVAYDC646K8E9HKQQ08SB9.avif\"]',NULL,1,'2026-05-17 20:14:05','2026-05-18 17:51:16'),(11,'The New CRETA','the-new-creta','SUV',297300000.00,'Spotlight in every move. SUV compact yang dinamis dan berjiwa muda, dilengkapi dengan konektivitas tercanggih.','[\"Hyundai Bluelink\",\"Bose Sound System\",\"Ventilated Seats\",\"Panoramic Sunroof\"]','[{\"name\":\"Active MT\",\"price\":297300000,\"transmission\":\"Manual 6-Speed\",\"engine\":\"Smartstream G1.5 MPI\",\"key_features\":[\"8-inch Touchscreen\",\"16-inch Silver Alloy Wheels\",\"Dual Airbags\",\"Tilt Steering\"]},{\"name\":\"Trend IVT\",\"price\":319300000,\"transmission\":\"IVT (Intelligent Variable)\",\"engine\":\"Smartstream G1.5 MPI\",\"key_features\":[\"Hyundai Bluelink\",\"Wireless Smartphone Charger\",\"Rear View Monitor\",\"Rear USB Charger\"]},{\"name\":\"Style IVT\",\"price\":383800000,\"transmission\":\"IVT (Intelligent Variable)\",\"engine\":\"Smartstream G1.5 MPI\",\"key_features\":[\"LED Headlamps\",\"Panoramic Sunroof\",\"Bose Sound System (8 Speakers)\",\"Ventilated Seats\"]},{\"name\":\"Prime IVT\",\"price\":416800000,\"transmission\":\"IVT (Intelligent Variable)\",\"engine\":\"Smartstream G1.5 MPI\",\"key_features\":[\"Hyundai SmartSense Safety\",\"Red Accent Exterior Lines\",\"Tire Pressure Monitoring System\",\"10.25-inch TFT Cluster\"]}]','cars/01KRYXE2C0WT0YVMJWXCN2VR5R.png','cars/hero/01KRYXE2CBR7PERFE68CV224NW.webp','[\"cars\\/gallery\\/01KRYXGS0XBD4D9DPPJMCXXBNZ.webp\",\"cars\\/gallery\\/01KRYXGS13TJMTRQX3KXJM8QCS.webp\",\"cars\\/gallery\\/01KRYXGS17M67SFG4ZQCQWYEEV.webp\",\"cars\\/gallery\\/01KRYXGS1DY58CDZ0BJ4EP2C2E.webp\",\"cars\\/gallery\\/01KRYXGS1KDFB36ATFK6Q9F65D.webp\",\"cars\\/gallery\\/01KRYXGS1RXEP7C27ENZB006CV.webp\"]',NULL,1,'2026-05-17 20:23:19','2026-05-18 18:27:32'),(12,'STARGAZER','stargazer','MPV',262300000.00,'Bintang Baru Keluarga. MPV yang dirancang khusus untuk kenyamanan dan keamanan berkendara bersama keluarga tercinta.','[\"Captain Seat\",\"Tire Pressure Monitoring\",\"Spacious Cabin\",\"Hyundai SmartSense\"]','[{\"name\":\"Active MT\",\"price\":262300000,\"transmission\":\"Manual 6-Speed\",\"engine\":\"Smartstream G1.5 MPI\",\"key_features\":[\"Halogen Headlamps\",\"15-inch Steel Wheels\",\"2 Speakers Audio\",\"Dual Airbags\"]},{\"name\":\"Trend IVT\",\"price\":280200000,\"transmission\":\"IVT (Intelligent Variable)\",\"engine\":\"Smartstream G1.5 MPI\",\"key_features\":[\"8-inch Display Audio\",\"16-inch Alloy Wheels\",\"Rear View Monitor\",\"Hyundai Bluelink\"]},{\"name\":\"Style IVT\",\"price\":305300000,\"transmission\":\"IVT (Intelligent Variable)\",\"engine\":\"Smartstream G1.5 MPI\",\"key_features\":[\"Full LED Headlamps\",\"4.2-inch Supervision Cluster\",\"6 Speakers Audio\",\"Cruise Control\"]},{\"name\":\"Prime IVT\",\"price\":320900000,\"transmission\":\"IVT (Intelligent Variable)\",\"engine\":\"Smartstream G1.5 MPI\",\"key_features\":[\"Hyundai SmartSense Safety\",\"Ambient Mood Lighting\",\"Leather Seats\",\"Bose Premium Sound System\"]}]','cars/01KRYXVD8XBCDXBHTN7HTHA740.png','cars/hero/01KRYXVD99XR84E3FX8NHKQHN5.avif','[\"cars\\/gallery\\/01KRYXVD9H7SVE8MPNX472GYE9.avif\",\"cars\\/gallery\\/01KRYXVD9N1CSH1M2793MNTSB4.avif\",\"cars\\/gallery\\/01KRYXVD9TDEBN71P4JVARDT7C.avif\",\"cars\\/gallery\\/01KRYXVD9XJKVS32QDBJMGEGEN.avif\",\"cars\\/gallery\\/01KRYXVDA1HSEZD0480A3WQ9DS.avif\",\"cars\\/gallery\\/01KRYXVDA42Z5XRHCPXNK16XJZ.webp\",\"cars\\/gallery\\/01KRYXVDAB7SPNBC0J8AH5KEPN.avif\",\"cars\\/gallery\\/01KRYXVDAEQZDCENYB6KGZX9YC.avif\"]',NULL,1,'2026-05-17 20:26:46','2026-05-18 18:33:20'),(13,'Santa Fe ','santa-fe','SUV',740500000.00,NULL,'[\"6 airbag\",\"SUV\",\"Hyundai smartsense\",\"Kamera 360\",\"SOS Button\",\"Bluelink\"]',NULL,'cars/01KRWJDPJJSD2PYJQJFH221RMJ.png',NULL,'[]',NULL,1,'2026-05-17 20:33:25','2026-05-17 20:35:08'),(14,'IONIQ 5','ioniq-5','EV',782000000.00,'Power your world with the IONIQ 5. Era baru mobil listrik murni yang menggabungkan desain retro-futuristis dengan teknologi V2L revolusioner.','[\"V2L Technology\",\"Ultra-fast Charging\",\"Sustainable Materials\",\"Vision Roof\"]','[{\"name\":\"Standard Range Prime\",\"price\":782000000,\"transmission\":\"Single Speed Reduction Gear\",\"engine\":\"Electric Motor (58 kWh Battery)\",\"key_features\":[\"Range 384 km\",\"V2L (Vehicle-to-Load) Outlets\",\"Hyundai SmartSense\",\"LED Headlamps\"]},{\"name\":\"Standard Range Signature\",\"price\":823000000,\"transmission\":\"Single Speed Reduction Gear\",\"engine\":\"Electric Motor (58 kWh Battery)\",\"key_features\":[\"Range 384 km\",\"Bose Premium Audio\",\"Premium Relaxation Seats\",\"Parametric Pixel LED Light\"]},{\"name\":\"Long Range Prime\",\"price\":809000000,\"transmission\":\"Single Speed Reduction Gear\",\"engine\":\"Electric Motor (72.6 kWh Battery)\",\"key_features\":[\"Range 481 km\",\"V2L (Vehicle-to-Load) Outlets\",\"Hyundai SmartSense\",\"19-inch Alloy Wheels\"]},{\"name\":\"Long Range Signature\",\"price\":895000000,\"transmission\":\"Single Speed Reduction Gear\",\"engine\":\"Electric Motor (72.6 kWh Battery)\",\"key_features\":[\"Range 481 km\",\"Vision Roof\",\"Bose Premium Sound System\",\"Premium Relaxation Seats\"]}]','cars/01KRYY127MKSJJ8T2BHCMEY83M.webp','cars/hero/01KRYY127TB5W5KZKRHZYK41R4.avif','[\"cars\\/gallery\\/01KRYY12818GNVAZ075387NHQC.avif\",\"cars\\/gallery\\/01KRYY1285J5FW7YGS8Q1XDRYY.avif\",\"cars\\/gallery\\/01KRYY128BB7VXHYE62KS4JNF3.avif\",\"cars\\/gallery\\/01KRYY128F44MX8SGT63715C8C.avif\",\"cars\\/gallery\\/01KRYY128KV6JSYWVV3RS66ANE.avif\"]',NULL,1,'2026-05-18 18:19:16','2026-05-18 18:36:25');
