INSERT INTO `posts` VALUES (2,'Masa Depan Berkendara: Menjelajahi Teknologi E-GMP pada Hyundai Ioniq Series','masa-depan-berkendara-menjelajahi-teknologi-e-gmp-pada-hyundai-ioniq-series','<p>Hyundai terus memimpin revolusi kendaraan listrik dengan platform E-GMP (Electric Global Modular Platform). Teknologi ini bukan sekadar baterai besar, melainkan arsitektur cerdas yang memungkinkan pengisian daya ultra-cepat dan ruang kabin yang jauh lebih luas.</p><p>Dengan sistem pengisian 800V, Ioniq 5 dapat terisi dari 10% ke 80% hanya dalam waktu 18 menit. Ini adalah standar baru dalam kenyamanan berkendara jarak jauh tanpa rasa khawatir akan waktu pengisian yang lama.</p>','posts/thumbnails/ioniq.png','News',1,'2026-05-10 10:52:25','2026-05-10 10:46:55','2026-05-10 10:52:25'),(3,'5 Rahasia Agar Performa Mesin Mobil Tetap Prima di Segala Kondisi Jalan','5-rahasia-agar-performa-mesin-mobil-tetap-prima-di-segala-kondisi-jalan','<p>Menjaga performa mesin tidak harus sulit. Kuncinya ada pada konsistensi perawatan rutin. Pertama, pastikan oli mesin diganti sesuai jadwal. Kedua, periksa tekanan ban secara berkala untuk efisiensi bahan bakar yang maksimal.</p><p>Selain itu, menggunakan bahan bakar dengan oktan yang sesuai rekomendasi pabrikan akan membantu menjaga kebersihan ruang bakar dan mencegah knocking pada mesin modern Hyundai Anda.</p>','posts/thumbnails/maintenance.png','Tips',1,'2026-05-10 10:52:25','2026-05-10 10:46:55','2026-05-10 10:52:25'),(4,'Eksklusif Bulan Ini: Penawaran Bunga 0% dan Hadiah Langsung untuk Pembelian STARGAZER','eksklusif-bulan-ini-penawaran-bunga-0-dan-hadiah-langsung-untuk-pembelian-stargazer','<p>Wujudkan impian keluarga Anda memiliki Hyundai STARGAZER bulan ini. Dapatkan paket cicilan ringan dengan bunga 0% hingga 2 tahun. Tidak hanya itu, setiap pembelian unit STARGAZER juga berhak mendapatkan voucher belanja senilai jutaan rupiah.</p><p>Promo ini berlaku terbatas hingga akhir bulan. Hubungi konsultan sales kami sekarang untuk mendapatkan simulasi kredit yang sesuai dengan budget Anda.</p>','posts/thumbnails/stargazer.png','Promo',1,'2026-05-10 10:52:25','2026-05-10 10:46:55','2026-05-10 10:52:25'),(5,'Keseruan Weekend Drive Bersama Komunitas Hyundai Gowa: Kebersamaan dalam Kenyamanan','keseruan-weekend-drive-bersama-komunitas-hyundai-gowa-kebersamaan-dalam-kenyamanan','<p>Pekan lalu, lebih dari 50 pemilik unit Hyundai berkumpul untuk acara Weekend Drive menuju pegunungan. Acara ini bertujuan untuk mempererat tali silaturahmi antar pemilik sekaligus mencoba ketangguhan fitur SmartSense di medan yang menantang.</p><p>Kenyamanan kabin dan fitur hiburan yang mumpuni membuat perjalanan jauh terasa singkat dan menyenangkan bagi seluruh keluarga peserta.</p>','posts/thumbnails/event.png','Event',1,'2026-05-10 10:52:25','2026-05-10 10:46:55','2026-05-10 10:52:25');
/*!40000 ALTER TABLE `posts` ENABLE KEYS */;
UNLOCK TABLES;

